export interface HardwarePosAuthSession {
    token: string;
    refreshToken?: string | null;
    userId: number;
    email: string;
    username: string;
    companyToken: string;
}

export interface HardwarePosLoginInput {
    baseUrl: string;
    companyToken: string;
    email: string;
    password: string;
}

const joinUrl = (baseUrl: string, path: string): string => (
    `${String(baseUrl).replace(/\/+$/, '')}${path.startsWith('/') ? path : `/${path}`}`
);

const normalizeApiBase = (input: string): string => {
    const trimmed = String(input || '').trim();
    if (!trimmed) {
        return '';
    }

    return trimmed.endsWith('/api/v1')
        ? trimmed
        : `${trimmed.replace(/\/+$/, '')}/api/v1`;
};

export class HardwarePosAuthClient {
    async login(input: HardwarePosLoginInput): Promise<HardwarePosAuthSession> {
        const baseUrl = normalizeApiBase(input.baseUrl);
        const loginResponse = await fetch(joinUrl(baseUrl, '/auth/login'), {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'x-company-token': input.companyToken
            },
            body: JSON.stringify({
                email: input.email,
                password: input.password
            })
        });

        const loginPayload = await loginResponse.json() as {
            success: boolean;
            data?: Record<string, unknown>;
            message?: string;
        };

        if (!loginResponse.ok || loginPayload.success !== true || !loginPayload.data?.token) {
            throw new Error(loginPayload.message || 'Hardware POS login failed.');
        }

        const token = String(loginPayload.data.token);
        const meResponse = await fetch(joinUrl(baseUrl, '/users/me'), {
            headers: {
                Authorization: `Bearer ${token}`,
                'x-company-token': input.companyToken
            }
        });

        const mePayload = await meResponse.json() as {
            success: boolean;
            data?: Record<string, unknown>;
            message?: string;
        };

        if (!meResponse.ok || mePayload.success !== true || !mePayload.data) {
            throw new Error(mePayload.message || 'Unable to load current cashier profile.');
        }

        return {
            token,
            refreshToken: loginPayload.data.refreshToken ? String(loginPayload.data.refreshToken) : null,
            userId: Number(mePayload.data.user_id ?? loginPayload.data.user_id ?? 0),
            email: String(mePayload.data.email ?? input.email),
            username: String(mePayload.data.username ?? mePayload.data.name ?? input.email),
            companyToken: input.companyToken
        };
    }
}
